// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: seedMarket with initial drugs
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.seedMarket{value: 1 ether}(100);

        // Now call DrugDealer() from the CEO address (the contract deployer)
        // The reference sets initialized = true in seedMarket, then DrugDealer does nothing to it
        // The bug sets initialized = false in seedMarket, then DrugDealer does nothing to it
        // So after DrugDealer, in the reference initialized is true, in bug it's false
        c.DrugDealer();

        // Check the value of initialized
        bool initialized = c.initialized();
        // The reference holds initialized == true; the bug breaks (initialized == false)
        assertTrue(initialized);
    }
}

