pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market to allow sellDrugs
        vm.deal(address(c), 10 ether);
        c.seedMarket(1000);

        // Get free kilos for msg.sender
        c.getFreeKilo();

        // Set ceoAddress to a known account
        address ceo = address(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        vm.prank(ceo);
        c.DrugDealer();

        // warp forward to have some drugs
        vm.warp(block.timestamp + 86400);

        // Now call sellDrugs from a non-ceo address
        vm.prank(address(0x1234));
        bool ok;
        try c.sellDrugs() {
            ok = true;
        } catch {
            ok = false;
