pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address CEO = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        address user = address(0x1234);

        // Seed market first
        vm.deal(CEO, 1 ether);
        vm.prank(CEO);
        c.seedMarket{value: 1 ether}(1000);

        // CEO calls DrugDealer() – only this call differs between reference and bug
        vm.prank(CEO);
        c.DrugDealer();

        // Record balance before buyDrugs
        uint256 balanceBefore = address(c).balance;

        // Non-CEO user buys drugs with 1 ETH
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();

        uint256 balanceAfter = address(c).balance;

        // The fee is sent to ceoAddress (4% of 1 ETH = 0.04 ETH).
        // Reference: ceoAddress = CEO, send succeeds, balance increases by 1 ether – 0.04 ether fee sent out
        // Bug: ceoAddress = address(0), send to address(0) reverts, so buyDrugs reverts entirely.
        // If buyDrugs reverts, balance does not change.
        // Assert that buyDrugs succeeded: balance increased (reference) vs didn't change (bug)
        assertTrue(balanceAfter > balanceBefore);
