// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Prepare two users
        address user1 = address(0x1);
        address user2 = address(0x2);

        // Give user1 enough ether to buy drugs
        vm.deal(user1, 1 ether);
        vm.deal(user2, 0 ether);

        // Step 1: seed the market with initial marketDrugs = 1 (non-zero) and small initial balance
        // We call seedMarket by pranking the ceoAddress (original in contract: 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26)
        // But we cannot prank that address without its private key; alternatively, we can construct a new contract
        // that sets ceoAddress to something we control. However, the contract is fixed; we must work around.
        // Since ceoAddress is set in constructor, we cannot change it, but we can call seedMarket by sending ether from any address?
        // Actually seedMarket requires marketDrugs == 0, but it's not restricted to ceoAddress; any address can call it.
        vm.prank(user1);
        c.seedMarket{value: 0}(10 ether); // set marketDrugs = 10 ether (10e18 wei) and initialized = true

        // Step 2: user1 gets free kilo so they have kilos > 0
        vm.prank(user1);
        c.getFreeKilo();

        // Step 3: Warp time forward so that drugs accumulate
        vm.warp(block.timestamp + 86400); // exactly 86400 seconds later

        // Step 4: User1 has claimedDrugs = 0 initially, but after warp, getMyDrugs will be Kilos * secondsPassed = 300 * 86400 = 25,920,000
        // To simplify, we can just call buyDrugs to give user1 some claimedDrugs directly.
        // Actually, let's have user1 buy drugs with some ether to create a claimable drug amount.
        // BuyDrugs calculates drugs bought based on msg.value and contract balance.
        // Contract balance after seedMarket? seedMarket sends 0 ether, so balance remains 0.
        // We need contract to have some balance for calculateDrugBuy to work.
        vm.deal(address(c), 1 ether); // give contract some eth
        vm.prank(user1);
        c.buyDrugs{value: 0.1 ether}();

        // Now user1 has claimedDrugs. Let's query it.
        uint256 user1Drugs = c.getMyDrugs();

        // If user1Drugs is too small, we can repeat or adjust. For simplicity, we want user1Drugs = 864000 exactly.
        // Since we cannot guarantee exact value, we choose a simpler path:
        // Directly set claimedDrugs via buyDrugs with a specific value? Not possible precisely.
        // Alternative: just use the warp method with Kilos.
        // Let's reset: deploy new C, use with block.timestamp = 0, seedMarket, getFreeKilo, warp exactly 86400 seconds.
        // After getFreeKilo, Kilos[user1] = 300. Then warp 86400 seconds: getDrugsSinceLastCollect = min(86400, 86400) * 300 = 25,920,000.
        // That's huge and not 864000. So we need to adjust warp time.
        // We want claimedDrugs = 864000. Since getMyDrugs = claimedDrugs + getDrugsSinceLastCollect, and we clear claimedDrugs on collect,
        // we can set claimedDrugs via buyDrugs before collect. But we need exact 864000.
        // Simpler: create a scenario where collectDrugs adds to marketDrugs an amount proportional to some value.
        // The bug changes divisor from 10 to 20, so for a given drugUsed, marketDrugs increase is half.
        // We must ensure drugUsed is same in both cases, which it will be since getMyDrugs() is same.
        // So we just need any drugUsed > 0. For a concrete test, we can calculate drugUsed from getMyDrugs after some setup.
        // Let's use a specific warp time to achieve drugUsed = 10 (just for demonstration).
        // Actually, we need to pass the test: pick a concrete scenario where divergence appears.
        // Given the instructions, we can just assert marketDrugs after collectDrugs with some arbitrary drugUsed.
        // Let's make it simple: warp 1 second after getFreeKilo, so getDrugsSinceLastCollect = 1 * 300 = 300.
        // claimedDrugs initially 0, so getMyDrugs = 300.
        // Then collectDrugs will add to marketDrugs: 300/10 = 30 in reference, 300/20 = 15 in bug.
        // We assert marketDrugs == 30 (reference) vs 15 (bug). But marketDrugs starts at 10 ether (10e18).
        // After seedMarket, marketDrugs = 10e18. After collect, marketDrugs becomes 10e18 + 30 in reference, 10e18 + 15 in bug.
        // That is too large to check via uint256? We can check equality with 10e18 + 30.

        // Let's redo the whole sequence cleanly:
        c = new C(); // redeploy to have fresh state
        // seedMarket: set marketDrugs to some small number, say 1 for simplicity
        vm.prank(user1);
        c.seedMarket{value: 0}(1); // marketDrugs = 1, initialized = true

        // user1 gets free kilo
        vm.prank(user1);
        c.getFreeKilo();

        // warp 1 second
        vm.warp(block.timestamp + 1);

        // Now user1's getMyDrugs = 0 + 1*300 = 300
        // user2 acts as referrer
        vm.prank(user1);
        c.collectDrugs(user2);

        // After collectDrugs:
        // marketDrugs = previous (1) + drugUsed/10 = 1 + 30 = 31 in reference
        // In bug: 1 + 300/20 = 1 + 15 = 16
        // So assert marketDrugs == 31
        assertTrue(c.marketDrugs() == 31, "marketDrugs should be 31 in reference");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.seedMarket(1000);

        // Set up addresses
        address alice = address(0x1);
        address bob = address(0x2);

        // Give alice free kilos
        vm.prank(alice);
        c.getFreeKilo();

        // Warp time so alice accumulates drugs
        vm.warp(block.timestamp + 86400);

        // alice collects drugs, referring bob
        vm.prank(alice);
        c.collectDrugs(bob);

        // After collectDrugs, the referral bonus (SafeMath.div(drugsUsed,5) vs /4) goes to bob's claimedDrugs
        // Then bob calls collectDrugs (referring to himself is a no-op)
        vm.prank(bob);
        c.collectDrugs(bob);

        // Now check bob's Kilos: in the reference /5 gives smaller bonus-> fewer Kilos
        // In the bug /4 gives larger bonus-> more Kilos
        uint256 bobKilos = c.Kilos(bob);

        // The reference contract would produce a smaller value
        // We can assert that bobKilos is less than some threshold that only the bug surpasses
        // Knowing the reference produces 0 for bob (since drugsUsed for referral bonus is drugsUsed/5 which < 86400)
        // and the bug produces >0 because drugsUsed/4 >= 86400 triggers a kilo
        // So assert that bobKilos == 0 (true for reference, false for bug)
        assertTrue(bobKilos == 0, "Bob should have 0 kilos in reference, but bug gives >0");
    }
}

