    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market so initialized = true
        c.seedMarket(1000);

        // Alice and Bob addresses
        address alice = address(0x1234);
        address bob = address(0x5678);

        // Give Bob some claimedDrugs by having him buy drugs
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.buyDrugs{value: 1 ether}();

        // Bob collects drugs with Alice as referral. This triggers the referral bonus.
        vm.prank(bob);
        c.collectDrugs(alice);

        // In the reference, the referral bonus is divided by 5, so Alice's Kilos remain 0.
        // In the buggy version, the referral bonus is divided by 4, which may give Alice a non-zero amount.
        // Assert that Alice's Kilos should be 0 for the reference.
        assertTrue(c.Kilos(alice) == 0, "Bob should have 0 kilos in reference, but bug gives >0");
    }
}

