pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market with 1000 drugs
        vm.deal(address(this), 1 ether);
        c.seedMarket(1000);

        // Bob gets free kilos
        address bob = address(0x1);
        vm.prank(bob);
        c.getFreeKilo();

        // Bob collects drugs (no referral)
        vm.prank(bob);
        c.collectDrugs(address(0));

        // Alice gets free kilos
        address alice = address(0x2);
        vm.prank(alice);
        c.getFreeKilo();

        // Alice collects drugs referring Bob
        vm.prank(alice);
        c.collectDrugs(bob);

        // Check Bob's claimedDrugs
        uint256 bobClaimed = c.claimedDrugs(bob);

        // In reference: Bob gets alice's drugsUsed/5 = (86400*0)/5 = 0
        // In bug: Bob gets alice's drugsUsed/4 = 0
        // Actually alice's claimedDrugs is 0 after getFreeKilo and collect, so drugsUsed = 0
        // This means the test doesn't distinguish either.
        // We need a different scenario: let's use buyDrugs to give Alice positive claimedDrugs
        // Reset by deploying a new contract
        c = new C();

        // Seed the market
        c.seedMarket(1000);

        // Bob gets free kilos
        vm.prank(bob);
        c.getFreeKilo();

        // Bob waits 86400 seconds to accumulate drugs
        vm.warp(block.timestamp + 86400);

        // Bob collects drugs (no referral) — this also sets his claimedDrugs to 0 after adding new kilos
        vm.prank(bob);
        c.collectDrugs(address(0));

        // Alice buys drugs to get claimedDrugs
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.buyDrugs{value: 1 ether}();

        // Alice collects drugs referring Bob
        vm.prank(alice);
        c.collectDrugs(bob);

        // Check Bob's claimedDrugs now
        uint256 bobClaimedAfter = c.claimedDrugs(bob);

        // In reference: referral bonus = drugsUsed / 5
        // In bug: referral bonus = drugsUsed / 4
        // Since drugsUsed > 0, these differ
        assertTrue(bobClaimedAfter > 0, "Bob should have referral bonus");
        // This assertion passes on both, but the exact value differs.
        // We'll directly assert the exact value for reference
        uint256 expectedReferralBonusRef = c.getMyDrugs() / 5; // This won't match due to state changes
        // Let's just force the assertion: we know the bug gives more, so we check equality with reference behavior
        // Actually we need the concrete numbers. Let's compute:
        // After buyDrugs(1 ether), alice's claimedDrugs depends on contract balance and marketDrugs.
        // The next collectDrugs will compute drugsUsed = claimedDrugs + secondsPassed * kilos.
        // Since alice's kilos = 0 (she didn't getFreeKilo), drugsUsed = claimedDrugs from buy.
        // So we need to calculate the exact drugsUsed.
        // Let's use vm.warp to make it simpler: wait 86400 seconds after buy, then alice's kilos = 0 => drugsUsed still same.
        // We'll just hardcode the expected reference value by reading the state after setup.
        // Actually simpler: we know the bug gives a larger referral bonus because dividing by 4 instead of 5.
        // So we can assert that Bob's claimedDrugs in reference is exactly (drugsUsed/5) and in bug (drugsUsed/4).
        // Since we can't recompute easily, we'll assert c.claimedDrugs(bob) == (c.getMyDrugsForAlice() / 5) but that's not stored.
        // The simplest: we know the bug's referral is larger, so we can assert that c.claimedDrugs(bob) < c.claimedDrugs(bob) + 1? No.
        // Let's just do: the reference gives bobClaimedAfter == specific computed value; the bug gives a different one.
        // Compute it: after buyDrugs(1 ether), let's get Alice's claimedDrugs before collect
        uint256 aliceClaimedBefore = c.claimedDrugs(alice);
        // Then drugsUsed = aliceClaimedBefore (since kilos=0 and no time passed)
        uint256 drugsUsed = aliceClaimedBefore;
        uint256 expectedRefBonus = drugsUsed / 5;
        uint256 expectedBugBonus = drugsUsed / 4;
        // The actual Bob's claimedDrugs should be the referral bonus (0 before)
        // assertTrue(bobClaimedAfter == expectedRefBonus); would pass on ref, fail on bug
        assertTrue(bobClaimedAfter == expectedRefBonus);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: Seed market with some drugs and give Bob some Kilos
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.seedMarket{value: 1 ether}(1000);

        // Bob gets free kilos
        vm.prank(address(0x2));
        c.getFreeKilo();

        // Warp time so Bob accumulates more than 0 drugs
        vm.warp(block.timestamp + 86400 + 1); // just over 1 day

        // Bob collects drugs with referral to Alice
        vm.prank(address(0x2));
        c.collectDrugs(address(0x3));

        // After collect, Alice should have claimedDrugs from referral.
        // Reference: claimedDrugs[Alice] += drugsUsed / 5
        // Bug: claimedDrugs[Alice] += drugsUsed / 4
        // Bob's drugsUsed = claimedDrugs[Bob] + getDrugsSinceLastCollect(Bob)
        // At this point, claimedDrugs[Bob] was 0, Kilos[Bob]=300, time since lastCollect = 86401 -> min=86400 -> drugsUsed = 86400*300 = 25,920,000
        // Reference: Alice gets 25,920,000/5 = 5,184,000
        // Bug: Alice gets 25,920,000/4 = 6,480,000
        // So reference getMyDrugs(Alice) = 5,184,000, bug = 6,480,000
        uint256 aliceDrugs = c.getMyDrugs();
        assertTrue(aliceDrugs == 5184000 || aliceDrugs == 6480000, "Alice drugs differ");
        // To make it pass on reference and fail on bug:
        assertTrue(aliceDrugs == 5184000);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup seed market with 1 drug and minimal ether
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1);

        // Alice gets free kilo (300 kilos)
        address alice = vm.addr(1);
        vm.prank(alice);
        c.getFreeKilo();

        // Bob collects drugs with referral to Alice.
        // The referral bonus is drugsUsed/5 (reference) vs drugsUsed/4 (bug).
        // We need drugsUsed such that floor(drugsUsed/5) == 0 but floor(drugsUsed/4) >= 1.
        // DRUGS_TO_PRODUCE_1KILO = 86400, so newKilo = drugsUsed / 86400.
        // For Alice to gain 1 kilo from referral, we need referral bonus >= 86400.
        // The referral bonus is drugsUsed/5 or drugsUsed/4.
        // We choose drugsUsed = 86400 * 1; then drugsUsed/5 = 17280, still less than 86400 => no kilo.
        // drugsUsed/4 = 21600, also less. Need drugsUsed large enough.
        // Actually, Alice's Kilos increase only when referral bonus >= 86400.
        // So set drugsUsed = 86400 * 5 = 432000 => reference: 432000/5 = 86400 exactly => 1 new kilo.
        // But we want reference to give 0 kilos? Let's recalc:
        // Reference: referral = drugsUsed/5 = 86400 => Alice gets exactly 1 kilo.
        // Bug: referral = drugsUsed/4 = 108000 => also 1 kilo, no difference.
        // To differentiate, we need reference < 86400 and bug >= 86400.
        // So pick drugsUsed = 86400 * 4 = 345600 => reference: 345600/5 = 69120 (<86400, no kilo); bug: 345600/4 = 86400 (exactly 1 kilo).
        // So Alice's Kilos: reference 300, bug 301.
        // But we also need Bob's getMyDrugs() to be at least 345600.
        // Bob gets free kilo: 300 kilos, and time passes.
        // After getFreeKilo, warp forward 86400 seconds to produce 86400 * 300 drugs? That's huge.
        // Actually we can directly set Bob's claimedDrugs by him buying drugs or using seed.
        // Simpler: Bob buys drugs with enough ether to get claimedDrugs = 345600.
        address bob = vm.addr(2);
        vm.deal(bob, 10 ether);
        vm.prank(bob);
        // Buy drugs: calculateDrugBuy determines how many drugs per ether.
        // We'll just give Bob a huge amount by mining the difference.
        // Better approach: call getFreeKilo for Bob, then warp to accumulate.
        vm.prank(bob);
        c.getFreeKilo();
        // Bob has 300 kilos, need 345600 drugs. Each second produces Kilos[Bob] drugs = 300.
        // So need 345600/300 = 1152 seconds.
        vm.warp(block.timestamp + 1152);
        // Now Bob's getMyDrugs() = claimedDrugs (0) + 1152*300 = 345600.
        // Bob collects with referral to Alice.
        vm.prank(bob);
        c.collectDrugs(alice);

        // Check Alice's Kilos:
        uint256 aliceKilos = c.Kilos(alice);
        // Reference: referral bonus = 345600/5 = 69120, which does NOT produce a new kilo (needs 86400), so Kilos stays 300.
