import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: seed market with 1 drugs and 1 ether
        vm.deal(address(this), 2 ether);
        c.seedMarket{value: 1 ether}(1);

        // CEO calls DrugDealer()
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.prank(ceo);
        c.DrugDealer();

        // User A (different address) calls buyDrugs with 1 ether
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();

        // Check claimedDrugs[user] — it will differ between reference and bug
        uint256 drugs = c.claimedDrugs(user);
        assertTrue(drugs == 942857142857142857); // reference value; bug gives different
    }
}

