pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: seed market and give Alice some kilos
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 0.1 ether}(100);

        // Alice gets free kilos
        address alice = address(0x1);
        address bob = address(0x2);
        vm.prank(alice);
        c.getFreeKilo();

        // Warp time so Alice accumulates drugs
        vm.warp(block.timestamp + 86401); // more than 1 day

        // Alice collects with Bob as referral
        vm.prank(alice);
        c.collectDrugs(bob);

        // Check Bob's claimedDrugs – reference adds 20% of Alice's drugsUsed
        // drugsUsed = 86400 * 300 / 86400 = 300 (since 1 kilo produces 1 drug per second, and 86400 sec passed with 300 kilos)
        // Actually getMyDrugs for Alice: claimedDrugs[alice] was 0, lastCollect[alice] set to block.timestamp after seedMarket?
        // After seedMarket lastCollect[alice] is 0, so getDrugsSinceLastCollect returns min(86400, 86401) * 300 = 86400*300 = 25920000
        // drugsUsed = 0 + 25920000
        // 20% = 5184000
        uint256 bobClaimed = c.claimedDrugs(bob);
        assertTrue(bobClaimed == 5184000, "Bob should have received referral bonus");
    }
}

