pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.seedMarket{value: 1 ether}(1000);

        vm.prank(user);
        c.getFreeKilo();

        vm.warp(86400);

        uint256 initialBalance = user.balance;

        vm.prank(user);
        c.sellDrugs();

        uint256 finalBalance = user.balance;

        bool soldMoreThanExpected = finalBalance > initialBalance;
        assertTrue(soldMoreThanExpected);
    }
}

